#!/usr/bin/env bash
set -euo pipefail
repo="$(cd "$(dirname "$0")/.."&&pwd)";root="${1:-$repo/build/fg_dynamic_module23/macos/run}";[[ ! -e "$root" ]];mkdir -p "$root/build";a="$repo/evidence/checkpoints/2026-08-31-sm120-rcp-rom/external-evidence-sm120-rcp-rom.tar.gz";tar -xOf "$a" work/g23-rcp-architecture/m3-rcp-rom/correction-rom.bin >"$root/build/rom";xcrun -sdk macosx metal -std=metal3.1 -fno-fast-math -ffp-contract=off -Wno-unused-variable -Wno-unused-function -c "$repo/src/fg_dynamic_module23/dynamic_module23_mode0.metal" -o "$root/build/k.air";xcrun -sdk macosx metallib "$root/build/k.air" -o "$root/build/k.metallib";xcrun -sdk macosx clang++ -std=c++20 -fobjc-arc -Wno-unused-function "$repo/src/fg_dynamic_module23/macos_probe.mm" -framework Foundation -framework Metal -o "$root/build/p";for r in 720p 1080p 1440p 4k;do for ph in reset generated;do for z in a5 5a;do for q in a b;do id="$r-$ph-poison-$z-process-$q";mkdir -p "$root/$id";m=hash-only;[[ "$z$q" == a5a ]]&&m=full;"$root/build/p" "$root/build/k.metallib" "$root/build/rom" "$root/$id" "$id" "$z" "$r" "$ph" "$m">"$root/$id/stdout" 2>"$root/$id/stderr";done;done;done;done;echo result=pass
